lib = r'''
import numpy as np, json
LBL = ['coverage_grant','exclusion','premium_payment','deductible_limits','claims_procedure','definitions','term_cancellation_renewal','conditions_duties']
RES = np.array([83,88,222,254,444,495,506,601])
KEEP = np.setdiff1d(np.arange(768), RES)
def labels():
    P=[json.loads(l) for l in open('practice.jsonl')]
    return np.array([LBL.index(p['label']) for p in P])
def folds(y, k=5, seed=0):
    rng=np.random.RandomState(seed); f=np.zeros(len(y),int)
    for c in np.unique(y):
        idx=np.where(y==c)[0]; rng.shuffle(idx); f[idx]=np.arange(len(idx))%k
    return f
def ridge_fit(X, y, lam, C=8):
    mu=X.mean(0); Xc=X-mu; Y=np.eye(C)[y]; Y=Y-Y.mean(0)
    d=X.shape[1]
    W=np.linalg.solve(Xc.T@Xc+lam*np.eye(d), Xc.T@Y)
    b=-mu@W + np.eye(C)[y].mean(0)
    return W,b
def cv_acc(X, y, lams=(1,10,100,1000), k=5, seeds=(0,), std=False, ret_scores=False):
    out={}
    if std: X=(X-X.mean(0))/(X.std(0)+1e-6)
    for lam in lams:
        accs=[]; S=np.zeros((len(y),8))
        for s in seeds:
            f=folds(y,k,s)
            for i in range(k):
                tr=f!=i; te=f==i
                W,b=ridge_fit(X[tr],y[tr],lam); S[te]=X[te]@W+b
            accs.append((S.argmax(1)==y).mean())
        out[lam]=float(np.mean(accs))
        if ret_scores: out[('S',lam)]=S.copy()
    return out
def load_base():
    d=np.load('base_feats.npz'); return d
'''
