def whiten_fit(X, r=384, eps=1e-3):
    mu=X.mean(0); U,S,Vt=np.linalg.svd(X-mu,full_matrices=False); 
    P=Vt[:r].T/ (S[:r]/np.sqrt(len(X)))  # unit-variance PCA
    return mu,P
def head_cv(X, y, kind, k=10, seeds=(0,), lams=(0.01,0.1,1), **kw):
    res={lam:[] for lam in lams}
    for s in seeds:
        f=folds(y,k,s); S={lam:np.zeros((len(y),8)) for lam in lams}
        for i in range(k):
            tr=f!=i; te=f==i
            mu,P=whiten_fit(X[tr],kw.get('r',384)); Z=(X-mu)@P; Z/=np.sqrt(Z.shape[1])  # rms norm ~1
            if kind=='anchor':
                rng=np.random.RandomState(i); A=Z[tr][rng.choice(tr.sum(),768,replace=False)]
                G=Z@A.T; F=np.tanh(kw['a']*G+kw['b'])
            elif kind=='rf':
                rng=np.random.RandomState(i); Wr=rng.randn(Z.shape[1],768)*kw['s']; F=np.tanh(Z@Wr*np.sqrt(Z.shape[1])/np.sqrt(Z.shape[1]))
            elif kind=='lin': F=Z
            for lam in lams:
                W,b=ridge_fit(F[tr],y[tr],lam); S[lam][te]=F[te]@W+b
        for lam in lams: res[lam].append((S[lam].argmax(1)==y).mean())
    return {lam:round(float(np.mean(v)),4) for lam,v in res.items()}
