def sor_cv(X, y, fn, k=10, seeds=(0,), lams=(0.01,0.1,1), nanc=768, jit=1e-6):
    res={lam:[] for lam in lams}
    for s in seeds:
        f=folds(y,k,s); S={lam:np.zeros((len(y),8)) for lam in lams}
        for i in range(k):
            tr=f!=i; te=f==i
            mu=X[tr].mean(0); Z=X-mu; Z=Z/np.linalg.norm(Z,axis=1,keepdims=True)
            rng=np.random.RandomState(i+100*s); ai=rng.choice(tr.sum(),nanc,replace=False); A=Z[tr][ai]
            F=fn(Z@A.T); Kaa=fn(A@A.T)
            Ftr=F[tr]; fm=Ftr.mean(0); Fc=Ftr-fm; Y=np.eye(8)[y[tr]]; ym=Y.mean(0)
            for lam in lams:
                w=np.linalg.solve(Fc.T@Fc+lam*Kaa+jit*np.eye(nanc), Fc.T@(Y-ym))
                S[lam][te]=(F[te]-fm)@w+ym
        for lam in lams: res[lam].append((S[lam].argmax(1)==y).mean())
    return {lam:round(float(np.mean(v)),4) for lam,v in res.items()}
