def cv3(na, extra=('M0',), lam=0.02, c0=0.5, seeds=(0,1,2), mode='piv'):
    M=F['M9']; C=F['C9']; res=[]
    for sd in seeds:
        f=folds(y,10,sd); Y=np.eye(8)[y]; pred=np.zeros(len(y),int)
        for i in range(10):
            tr=f!=i; te=~tr; mu=M[tr].mean(0)
            Z=pool_z(M,C,10.0,mu); Zt=Z[tr]; Wf=anchor_dirs(Zt)
            if mode=='piv':
                Kc=gelu(Zt@Wf.T); Kc=.5*(Kc+Kc.T); piv=pivchol(Kc,na); Wd=Wf[piv]
            else:
                # per-class kmeans (few Lloyd steps on cosine) -- closed-form-ish clustering of activations
                rng=np.random.RandomState(sd); A=Zt/np.linalg.norm(Zt,axis=1,keepdims=True); yt=y[tr]; cents=[]
                for cl in range(8):
                    Ac=A[yt==cl]; kc=na//8; Cn=Ac[rng.choice(len(Ac),kc,replace=False)]
                    for it in range(10):
                        asg=(Ac@Cn.T).argmax(1)
                        for j in range(kc):
                            if (asg==j).any(): v=Ac[asg==j].mean(0); Cn[j]=v/np.linalg.norm(v)
                    cents.append(Cn)
                Cn=np.concatenate(cents); Cn[:,RES]=0; Wd=Cn/np.linalg.norm(Cn,axis=1,keepdims=True)/np.sqrt(768)
            Kaa=gelu(Wd@Wd.T*768); Phi=feats(Z,Wd)
            Lin=np.concatenate([lin_feats(F[e],tr) for e in extra],1)
            coef,b=fit(Phi[tr],Lin[tr],Y[tr],Kaa,lam,c0/len(extra))
            pred[te]=(np.concatenate([Phi[te],Lin[te]],1)@coef+b).argmax(1)
        res.append((pred==y).mean())
    return round(np.mean(res),4), np.round(res,4)
